jQuery(document).ready(function($){$('#download-table tbody').sortable({items:'tr',cursor:'move',handle:'.handle',});$('#add-row').on('click',function(){var row=$('.empty-d-row').clone(true);row.removeClass('empty-d-row').css('display','table-row');;row.find('input').val('');row.insertBefore('#download-table tbody > tr:first');return false;});$('#download-table').on('click','.remove-btn',function(){$(this).parents('tr').remove();return false;});var rangeInput=$('.range-input');var tooltip=$('.tooltip');rangeInput.on('input',function(e){tooltip.text(e.target.value);});$('.upload-screenshot-btn').on('click',function(){var button=$(this);var target_field_id=button.data('target');var custom_uploader=wp.media({title:'Choose Image',button:{text:'Choose Image'},multiple:false});custom_uploader.on('select',function(){var attachment=custom_uploader.state().get('selection').first().toJSON();$('#'+target_field_id).val(attachment.url);});custom_uploader.open();});$('#add-screenshot-btn').on('click',function(){var row=$('.empty-screenshot-row').clone(true);row.removeClass('empty-screenshot-row').css('display','table-row');var counter=$('.upload-screenshot-btn').length+1;row.find('input').attr('id','screenshot-url-'+counter);row.find('.upload-screenshot-btn').attr('id','screenshot-btn-'+counter);row.find('.upload-screenshot-btn').attr('data-target','screenshot-url-'+counter);row.insertBefore('#screenshots-table tbody>tr:last');return false;});$('.remove-screenshot-btn').on('click',function(){$(this).parents('tr').remove();return false;});var mediaUploader;$('#category-icon-upload-button').on('click',function(e){e.preventDefault();if(mediaUploader){mediaUploader.open();return;}
mediaUploader=wp.media({title:'Choose Icon',button:{text:'Select'},library:{type:['image/svg+xml','image/png']},multiple:false});mediaUploader.on('select',function(){var attachment=mediaUploader.state().get('selection').first().toJSON();$('#category-icon').val(attachment.url);});mediaUploader.open();});});